\beq\label{prob}
\begin{aligned}
\min_{x\in\mcX}&\quad f(x) :=\bbE[\tilde f(x,\xi)]\\
\mbox{s.t.}&\quad c(x)=0,
\end{aligned}
\eeq

where $\xi$ is a random variable with sample space $\Xi$, $\tf(\cdot,\xi)$ is continuously differentiable for each $\xi\in\Xi$,  $c:\rr^n\to\rr^m$ is a deterministic smooth mapping, and $\mcX\subseteq \rr^n$ is a simple closed convex set whose projection operator can be evaluated exactly.\footnote{For simplicity, we focus on problem \eqref{prob} with equality constraints only. However, our results can be directly extended to problems involving both equality and inequality constraints; see the concluding remarks for further details.} Problem \eqref{prob} arises in a variety of important areas, including energy systems \cite{shabazbegian2020stochastic}, healthcare \cite{shehadeh2022stochastic}, image processing \cite{luke2020proximal}, machine learning \cite{cuomo2022scientific,karniadakis2021physics},  network optimization \cite{bertsekasnetwork}, optimal control \cite{betts2010practical}, PDE-constrained optimization \cite{rees2010optimal}, resource allocation \cite{fontaine2020adaptive}, and transportation \cite{maggioni2009stochastic}. More applications can be found, for example, in \cite{bottou2018optimization,combettes2011proximal,jiang2018consensus,kushner2012stochastic,liu2015sparse}, and references therein.


\beq\label{def-Q} 
Q_\rho(x) := f(x) + \frac{\rho}{2} \|c(x)\|^2. 
\eeq

The following notation will be used throughout this paper.  Let $\rr_{>0}$ denote the set of positive real numbers, and  $\rr^n$ denote the Euclidean space of dimension $n$. The standard inner product and Euclidean norm are denoted by $\langle\cdot,\cdot\rangle$ and $\|\cdot\|$, respectively.  For any $r>0$, let $\cB(r)$ represent the Euclidean ball centered at the origin with radius $r$, that is, $\cB(r)=\{x:\|x\|\leq r\}$.  For any $t\in\rr$, let $t_+=\max\{t,0\}$ and $\lceil t \rceil$ denote the least integer greater than or equal to $t$.

A mapping $\phi$ is said to be \emph{$L_{\phi}$-Lipschitz continuous} on a set $\Omega$ if $\|\phi(x)-\phi(x')\| \leq L_{\phi} \|x-x'\|$ for all $x,x'\in \Omega$. Also, it is said to be \emph{$L_{\nabla\phi}$-smooth} on $\Omega$ if $\|\nabla\phi(x)-\nabla\phi(x')\| \leq L_{\nabla\phi} \|x-x'\|$ for all $x,x'\in \Omega$, where $\nabla \phi$ denotes the transpose of the Jacobian of $\phi$.  Given a nonempty closed convex set $\cC$, $\dist(x,\cC)$ denotes the Euclidean distance from $x$ to $\cC$, and $\Pi_\cC(x)$ denotes the Euclidean projection of $x$ onto $\Omega$.  In addition,  the normal cone of $\cC$ at any $x\in \cC$ is denoted by $\mcN_\cC(x)$.
Finally, we use $\tmcO(\cdot)$ to denote the asymptotic upper bound that ignores logarithmic factors.


\begin{assumption}\label{a1}
\begin{enumerate}[label=(\roman*)]
\item The optimal value $f^*$ of problem \eqref{prob}  and $Q_1^*:= \min_{x\in X} \{f(x)+\|c(x)\|^2/2\}$ are finite.
\item $f$ is differentiable and $L_f$-Lipschitz continuous in an open neighborhood of $\mcX$.
\item For each $\xi\in\Xi$, $\tf(\cdot,\xi)$ is differentiable on $\mcX$ and satisfies the following conditions:
\[
\bbE[\nabla\tf(x,\xi)]=\nabla f(x),\quad\bbE[\|\nabla\tf(x,\xi)-\nabla f(x)\|^2]\leq\sigma^2 \qquad \forall x\in\mcX
\]
for some constant $\sigma \geq 0$. 
\item The mapping $c$ is $L_c$-Lipschitz continuous and $L_{\nabla c}$-smooth in an open neighborhood of $\mcX$. Additionally, $\|c(x)\|\leq C_c$ for all $x\in\mcX$, and there exist constants $\gamma>0$ and $\theta\geq1$ such that
\beq \label{err-cond}
\dist\left(0,\nabla c(x)c(x)+\mcN_\mcX(x)\right)\geq\gamma\|c(x)\|^\theta\qquad \forall x\in\mcX.
\eeq
\end{enumerate}
\end{assumption}

\begin{align}
L:= L_c^2+C_cL_{\nabla c}.\label{def-L}
\end{align}

It follows from this and Assumption \ref{a1} that $\|c(x)\|^2/2$ is $L$-smooth on $\mcX$, and 
\beq\label{cf-bnd}
\|\nabla f(x)\|\leq L_f,\quad\|\nabla c(x)\|\leq L_c\qquad\forall x\in\mcX.
\eeq

\begin{algorithm}[H]
\caption{A stochastic first-order method with a truncated  recursive momentum for problem \eqref{prob}}\label{alg1}
\begin{algorithmic}[1]
\REQUIRE $x_1\in\mcX$, $\{\alpha_k\} \subset (0,1]$,  $\{\rho_k\}, \{\eta_k\} \subset \rr_{>0}$, and $L_f$ given in Assumption \ref{a1}.
\STATE Sample $\xi_1$ and set $g_1=\Pi_{\cB(L_f)}(\nabla\tf(x_1,\xi_1))$.
\FOR{$k=1,2,\dots$}
\STATE $G_k=g_k+\rho_k\nabla c(x_k)c(x_k)$.
\STATE $x_{k+1}=\Pi_\mcX(x_k-\eta_kG_k)$.
\STATE Sample $\xi_{k+1}$ and set $g_{k+1}=\Pi_{\cB(L_f)}\big(\nabla\tf(x_{k+1},\xi_{k+1})+(1-\alpha_k)(g_k-\nabla\tf(x_k,\xi_{k+1}))\big)$.
\ENDFOR
\end{algorithmic}
\end{algorithm}

\begin{assumption}\label{a-storm}
The function $\tf(x,\xi)$ satisfies the average smoothness condition:
\[
\bbE[ \|\nabla\tf(u,\xi)-\nabla\tf(v,\xi)\|^2]\leq \bL_{\nabla f}^2\|u-v\|^2\qquad \forall u,v\in\mcX.
\]
\end{assumption}

It can be observed that Assumption \ref{a-storm} implies that $\nabla f$ is $\bL_{\nabla f}$-smooth on $X$, that is,
\beq \label{bL-smooth}
 \|\nabla f(u)-\nabla f(v)\| \leq \bL_{\nabla f} \|u-v\| \qquad \forall u,v\in\mcX.
\eeq

\beq\label{def-h}
h(x) := \frac{1}{2}\|c(x)\|^2.
\eeq

One can observe from Assumption \ref{a1}(iv) that $h$ is $L$-smooth on $\mcX$, where $L$ is given in  \eqref{def-L}.

