\begin{lemma}\label{l-cnst2}
Let $\nu$, $\tK_1$, and $C_1$ be given in \eqref{def-para2}, \eqref{def-tK2} and \eqref{def-nuC2}, respectively. Suppose that Assumption \ref{a1} holds, and $\{x_k\}$ is generated by Algorithm \ref{alg1} with $\{\rho_k\}$, $\{\eta_k\}$ and $\{\alpha_k\}$ given in \eqref{def-para2}. Then  we have $\|c(x_k)\|^2\leq 2C_1k^{-2\nu/\theta}$ for all $k\geq\tK_1$.
\end{lemma}

\begin{lemma}\label{l-pfunc}
Suppose that Assumptions \ref{a1} and \ref{a-storm} hold. Let $\{g_k\}$ and $\{x_k\}$ be generated by Algorithm \ref{alg1}, and  let 
\beq\label{def-zeta}
\zeta_k=k^{\nu}/(2\log 3),
\eeq
where $\nu$ is defined in \eqref{def-para2}. Then for all $k\geq1$, we have
\begin{align}
&\bbE\left[Q_{\rho_k}(x_k)+\zeta_k\|g_k-\nabla f(x_k)\|^2\right] \leq Q_{\rho_1}(x_1)+\zeta_1\|g_1-\nabla f(x_1)\|^2+\frac{1}{2}\sum_{i=1}^{k-1}(\rho_{i+1}-\rho_i)\bbE\left[\|c(x_{i+1})\|^2\right] \nn \\
&+\frac{1}{2}\sum_{i=1}^{k-1}\left(\bL_{\nabla f}+\rho_iL-\eta_i^{-1}+12\zeta_{i+1}\bL_{\nabla f}^2\right)\bbE\left[\|x_{i+1}-x_i\|^2\right]+3\sigma^2\sum_{i=1}^{k-1}\zeta_{i+1}\alpha_i^2, \label{penalty-bnd}
\end{align}
where $\{\alpha_k\}$, $\{\rho_k\}$ and $\{\eta_k\}$ are given in Algorithm \ref{alg1}, $Q_\rho$  and $L$ are respectively defined in \eqref{def-Q} and \eqref{def-L},  and $\sigma$ and $\bL_{\nabla f}$  are given in Assumptions \ref{a1} and \ref{a-storm}, respectively.
\end{lemma}

\begin{lemma}\label{l-dist}
Suppose that Assumptions \ref{a1} and \ref{a-storm} hold, and $\{g_k\}$ and  $\{x_k\}$ are generated by Algorithm \ref{alg1}. Then for all $k\geq1$, we have
\beq \label{residual-bnd}
\dist^2\left(0,\nabla Q_{\rho_k}(x_{k+1})+\mcN_\mcX(x_{k+1})\right)\leq3\left(\eta_k^{-2}+(\bL_{\nabla f}+\rho_kL)^2\right)\|x_{k+1}-x_k\|^2+3\|g_k-\nabla f(x_k)\|^2,
\eeq
