\beq\label{prob}
\begin{aligned}
\min_{x\in\mcX}&\quad f(x) :=\bbE[\tilde f(x,\xi)]\\
\mbox{s.t.}&\quad c(x)=0,
\end{aligned}
\eeq

\beq\label{def-Q} 
Q_\rho(x) := f(x) + \frac{\rho}{2} \|c(x)\|^2. 
\eeq

\begin{align}
L:= L_c^2+C_cL_{\nabla c}.\label{def-L}
\end{align}

\begin{algorithm}[H]
\caption{A stochastic first-order method with a truncated  recursive momentum for problem \eqref{prob}}\label{alg1}
\begin{algorithmic}[1]
\REQUIRE $x_1\in\mcX$, $\{\alpha_k\} \subset (0,1]$,  $\{\rho_k\}, \{\eta_k\} \subset \rr_{>0}$, and $L_f$ given in Assumption \ref{a1}.
\STATE Sample $\xi_1$ and set $g_1=\Pi_{\cB(L_f)}(\nabla\tf(x_1,\xi_1))$.
\FOR{$k=1,2,\dots$}
\STATE $G_k=g_k+\rho_k\nabla c(x_k)c(x_k)$.
\STATE $x_{k+1}=\Pi_\mcX(x_k-\eta_kG_k)$.
\STATE Sample $\xi_{k+1}$ and set $g_{k+1}=\Pi_{\cB(L_f)}\big(\nabla\tf(x_{k+1},\xi_{k+1})+(1-\alpha_k)(g_k-\nabla\tf(x_k,\xi_{k+1}))\big)$.
\ENDFOR
\end{algorithmic}
\end{algorithm}

\begin{assumption}\label{a-storm}
The function $\tf(x,\xi)$ satisfies the average smoothness condition:
\[
\bbE[ \|\nabla\tf(u,\xi)-\nabla\tf(v,\xi)\|^2]\leq \bL_{\nabla f}^2\|u-v\|^2\qquad \forall u,v\in\mcX.
\]
\end{assumption}

It can be observed that Assumption ef{a-storm} implies that $
abla f$ is $ L_{
abla f}$-smooth on $X$, that is,
 eq \label{bL-smooth}
 \|
abla f(u)-
abla f(v)\| \leq  L_{
abla f} \|u-v\| \qquad  orall u,v\in\mcX.
\eeq

\beq\label{def-h}
h(x) := \frac{1}{2}\|c(x)\|^2.
\eeq

\begin{proof}
Let $G_k$ be given in Algorithm \ref{alg1}. For convenience, we define
\beq\label{l3-e1}
\widetilde G_k=\rho_k^{-1}G_k,\quad\tilde\eta_k=\rho_k\eta_k.
\eeq
 It then follows from these, \eqref{def-h}, and the expression of $x_{k+1}$ in Algorithm \ref{alg1} that
\beq\label{l3-x}
x_{k+1}=\Pi_\mcX(x_k-\eta_kG_k)=\Pi_\mcX(x_k-\tilde\eta_k\widetilde G_k),
\eeq
which implies that
\beq \label{subprob-opt1}
0\in x_{k+1}-x_k+\tilde\eta_k\widetilde G_k+\mcN_\mcX(x_{k+1})\quad\Rightarrow\quad \nabla h(x_{k+1})+\tilde\eta_k^{-1}(x_k-x_{k+1})-\widetilde G_k\in\nabla h(x_{k+1})+\mcN_\mcX(x_{k+1}).
\eeq

This together with the $L$-smoothness of $h$ yields
\begin{align*}
h(x_{k+1})& \leq h(x_k)+\langle\nabla h(x_k),x_{k+1}-x_k\rangle +\frac{L}{2}\|x_{k+1}-x_k\|^2\nn\\
&=h(x_k)+\langle\widetilde G_k,x_{k+1}-x_k\rangle+\langle\nabla h(x_k)-\widetilde G_k,x_{k+1}-x_k\rangle +\frac{L}{2}\|x_{k+1}-x_k\|^2\nn\\
& \leq h(x_k)-\tilde\eta_k^{-1}\|x_{k+1}-x_k\|^2+\langle\nabla h(x_k)-\widetilde G_k,x_{k+1}-x_k\rangle +\frac{L}{2}\|x_{k+1}-x_k\|^2.
\end{align*}
Using this and \eqref{l3-e2}, we obtain that
\beq\label{l3-e3}
h(x_{k+1})+2^{\theta-2}\gamma^2\tilde\eta_k[h(x_{k+1})]^{\theta}\leq h(x_k)+\frac{1}{2}(L^2\tilde\eta_k-\tilde\eta_k^{-1}+L)\|x_{k+1}-x_k\|^2+\frac{\tilde\eta_k}{2}\|\widetilde G_k-\nabla h(x_k)\|^2.
\eeq

